// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): AP Human Geography, Unit 4, Political Patterns and Processes
// (the course's public outline, topics 4.1-4.10; our own wording and questions, nothing copied). Taught: state, nation, nation-state,
// multinational, multistate and stateless nations, sovereignty and self-determination; colonialism, imperialism, neocolonialism and decolonization;
// territoriality and geopolitical ideas (Heartland, Rimland, domino theory, balance of power); boundary types (antecedent, subsequent, consequent,
// superimposed, relic, geometric) and maritime zones under UNCLOS (12 nautical miles of territorial sea, 24 of contiguous zone, 200 of exclusive economic zone;
// 1 nautical mile = 1.852 km); the functions of boundaries and four kinds of boundary dispute; internal boundaries, redistricting and gerrymandering
// (cracking and packing, with a fictional districting example); unitary and federal states; devolution and its factors; supranational organizations (UN, EU, ASEAN, AU)
// and other challenges to sovereignty; centripetal and centrifugal forces and their consequences.
// Every invented example, country and number is labelled fictional and chosen so each answer is whole or terminates; the factual questions are standard
// textbook statements, hedged where scholars disagree, and contested territories are described without taking a side.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 × 280 screen positions, converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 × 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push({v,col});},line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),circle:(x,y,r,col=0)=>circles.push({c:point(x,y),r,col}),note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col})};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const n=v=>v.toLocaleString('en-US');
const r4=v=>Math.round(v*1e4)/1e4;
const pct=v=>String(r4(v));
const list=a=>a.slice(0,-1).join(', ')+' and '+a.at(-1);
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['A fictional nation of 4 million people lives inside the borders of larger neighboring states and governs no state of its own. Which term fits best: nation-state, multinational state or stateless nation?',
 'A fictional coastal state claims waters out to 30 nautical miles from its coast. How many kilometers is that? Use 1 nautical mile = 1.852 kilometers.',
 'A fictional country\'s constitution divides power between a national government and regional governments, and neither can take away the other\'s powers. Which term fits best: unitary, federal or autocracy?',
 'A fictional province that has been ignored by its government for decades votes to demand separation. Is this a centripetal or a centrifugal force?'];
/* lettered choices, the right one moved to position k */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
/* sorted cases: [text, answer] */
const NATION=[
 ['A fictional country of 5 million people in which nearly everyone belongs to one nation, with a government that represents it.','nation-state'],
 ['A fictional country whose borders hold four distinct nations, each with its own language and homeland region.','multinational state'],
 ['A fictional nation of 6 million people with a shared language and homeland that has no state of its own.','stateless nation'],
 ['The Kurds, a people with a shared language and culture who live mainly across several countries without a state of their own, are often given as an example.','stateless nation'],
 ['A fictional state of 9 million people in which two nations, each with its own language, share one government.','multinational state']];
const BOUND=[
 ['A fictional boundary drawn before anyone had settled the area, with towns later built up to the line.','antecedent'],
 ['A fictional boundary drawn as a straight line along a parallel of latitude across thinly populated land.','geometric'],
 ['A fictional boundary drawn after settlement to follow the line between two language groups.','consequent'],
 ['A fictional boundary laid down by distant powers across a region, ignoring the groups living there.','superimposed'],
 ['A fictional former border between two states that merged long ago, still visible as ruined walls and old customs posts.','relic'],
 ['A fictional boundary set after settlement and then moved several times by treaty between two neighbors.','subsequent']];
const DISPUTE=[
 ['Two fictional states disagree about how to read a treaty phrase, "along the main channel of the river".','definitional'],
 ['Two fictional states agree that their border follows a ridge but disagree about where exactly the markers should stand.','locational'],
 ['Two fictional states quarrel over how many travelers may cross at a checkpoint and what goods are inspected.','operational'],
 ['Two fictional states argue over who may fish and drill in the waters of a shared bay.','allocational'],
 ['An old fictional treaty says the border follows "the high ground", and the two states read the words differently.','definitional'],
 ['Two fictional states disagree about who gets the oil found under their border.','allocational']];
const GERRY=[
 ['Most of one party\'s voters are placed in a single district that they win with 95 percent of the vote.','packing'],
 ['A party\'s voters are spread across several districts so that they are a minority in each.','cracking'],
 ['A fictional map draws one oddly shaped district to hold as many opposition voters as possible.','packing'],
 ['A fictional map splits a city\'s large minority community among four districts so it can no longer elect its preferred candidate.','cracking']];
const GOV=[
 ['The national government of a fictional country appoints all regional governors and can cancel their decisions.','unitary'],
 ['A fictional constitution gives regional governments their own taxes and courts that the national government cannot remove.','federal'],
 ['In a fictional state, local councils have only the powers that parliament lends them and can be reorganized by parliament.','unitary'],
 ['A fictional country has ten provinces that each write their own education laws, under a national constitution.','federal'],
 ['Most laws in a fictional country are made by one national legislature, and the regions follow them.','unitary'],
 ['A fictional country has a national legislature and also elected state legislatures with their own powers.','federal']];
const DEVO=[
 ['Mountains and a stretch of sea separate a fictional state\'s island provinces from its capital.','physical geography'],
 ['A fictional minority people in the north demands its own government.','ethnic separatism'],
 ['A fictional state claims land across its border because many people there share its ethnicity.','irredentism'],
 ['A rich fictional region objects to paying taxes that fund poorer regions.','economic differences'],
 ['Violent attacks by a fictional armed group target the capital to pressure the government.','terrorism']];
const ORG=[
 ['A global organization with a General Assembly where nearly every state has a seat.','the UN'],
 ['A union of European states with a parliament elected by voters in the member states, a common market and, for many members, a shared currency.','the EU'],
 ['An organization of Southeast Asian states, with its secretariat in Jakarta, that stresses economic cooperation and consensus.','ASEAN'],
 ['A continental organization of African states with headquarters in Addis Ababa, Ethiopia.','the African Union'],
 ['An organization whose Security Council has five permanent members.','the UN']];
const FORCE=[
 ['A fictional country adopts a national holiday and a flag that all regions celebrate.','centripetal'],
 ['A fictional minority group is denied the use of its language in schools and begins to demand its own state.','centrifugal'],
 ['A fictional government builds a railway linking every province to the capital.','centripetal'],
 ['A fictional region that earns most of the oil income resents sharing it with poorer provinces.','centrifugal'],
 ['A fictional national football team wins and delights citizens in every province.','centripetal'],
 ['A fictional country has two religions whose leaders call for separate laws and separate territories.','centrifugal']];
/* districting examples: [districts, voters per district, Orange votes in each] (the worked example in the steps is not among them) */
const SEATS=[[5,100,[62,38,54,45,47]],[5,100,[80,45,45,45,35]],[5,100,[55,55,55,20,20]],[4,200,[120,90,130,60]],[6,100,[51,49,51,49,51,49]]];
export default {
id:'geography-h-ap-hug-political-patterns-and-processes',subject:'geography',level:5,grade:9,standard:'AP Human Geography, Unit 4',
title:'Political patterns and processes',
goal:'Tell states, nations, nation-states, multinational states and stateless nations apart, explain sovereignty and the processes of colonialism and decolonization, classify boundaries and UNCLOS maritime zones, read gerrymandering and the way internal boundaries shape power, compare unitary and federal states, explain devolution and challenges to sovereignty such as supranational organizations, and weigh centripetal against centrifugal forces.',
points:20,
skills:{intro:'Introduction to political geography',processes:'Political processes',power:'Political power and territoriality',defining:'Defining political boundaries',function:'The function of political boundaries',internal:'Internal boundaries',governance:'Forms of governance',devolution:'Defining devolutionary factors',sovereignty:'Challenges to sovereignty',forces:'Centrifugal and centripetal forces'},
outline:[['4.1','Introduction to political geography',['intro']],['4.2','Political processes',['processes']],['4.3','Political power and territoriality',['power']],['4.4','Defining political boundaries',['defining']],['4.5','The function of political boundaries',['function']],['4.6','Internal boundaries',['internal']],['4.7','Forms of governance',['governance']],['4.8','Defining devolutionary factors',['devolution']],['4.9','Challenges to sovereignty',['sovereignty']],['4.10','Consequences of centrifugal and centripetal forces',['forces']]],
steps:[
 {skill:"intro",say:"Political geography studies how power and boundaries are organized across space. A state is a political unit with a defined territory, a permanent population, a government and sovereignty. A nation is a group of people who share a culture, history and sense of identity. A nation-state is a state whose people are largely one nation; few states match that exactly, since most hold more than one cultural group.",pic:scene('State, nation and nation-state',d=>{for(const [x,t1,t2,e,col] of [[62,'State','territory and rule','sovereign and recognized',0],[250,'Nation','shared identity','culture, history, language',1],[438,'Nation-state','the two coincide','rare in pure form',2]]){d.box(x,98,140,64,col);d.note(x+70,121,t1,col);d.note(x+70,144,t2,col);d.note(x+70,194,e,3);}d.line(206,130,244,130,3,1);d.line(394,130,432,130,3,1);d.note(320,232,'A state is political; a nation is cultural');}),
  check:{prompt:tryIt(TRY[0]),answer:'stateless nation',options:['stateless nation','nation-state','multinational state'],hint:'The nation lacks a state of its own.',pic:tab('The case',[['people','4 million, one nation'],['state of its own','none']])}},
 {skill:"intro",say:"Real maps are messier than the ideal. A multinational state contains more than one nation. A multistate nation stretches across the borders of more than one state. A stateless nation has no state of its own; the Kurds are often cited as an example. Sovereignty is a state's supreme authority over its territory, recognized by others, and self-determination is the principle that a people may decide its own political status.",pic:board('Kinds of states and nations',['Multinational state: one state, several nations','Multistate nation: one nation across several states','Stateless nation: a nation with no state of its own','Sovereignty: supreme authority within a territory','Self-determination: a people decides its own status'])},
 {skill:"processes",say:"Political maps change through processes. Colonialism is one state taking control of a territory and governing its people, often with settlers. Imperialism is the wider policy of extending a state's power over other places, directly or indirectly. European powers claimed most of Africa in the late 1800s, and the Berlin Conference of 1884-85 set rules for that claiming without African rulers at the table. Decolonization after 1945 produced many new states, and neocolonialism names continuing outside influence.",pic:{t:'timeline',events:['European colonies grow, 1500s on','Berlin Conference, 1884-85','WWII ends, 1945','Wave of decolonization, 1950s and 1960s','Neocolonial influence debated today']}},
 {skill:"power",say:"Territoriality is the attempt by a person, group or state to claim, control and defend an area. Geopolitics studies how geography shapes the power of states. Halford Mackinder argued that control of the interior of Eurasia, the Heartland, could give world power; Nicholas Spykman argued that the coastal Rimland mattered more. During the Cold War some US leaders held the domino theory, that one state falling to communism would pull its neighbors after it. These are theories, not laws.",pic:scene('Two geopolitical theories (schematic, not a map)',d=>{d.box(120,60,400,164,1);d.note(320,78,'Rimland: coastal edge (Spykman)',1);d.box(200,102,240,90,0);d.note(320,134,'Heartland',0);d.note(320,158,'interior of Eurasia (Mackinder)');d.note(320,236,'Each theory names a different key to power',3);})},
 {skill:"defining",say:"Boundaries are classified by when and how they were drawn. An antecedent boundary comes before dense settlement. A subsequent boundary is drawn after settlement and may be adjusted. A consequent boundary follows cultural differences such as language or religion. A superimposed boundary is forced on an area by outside powers, ignoring existing patterns. A relic boundary no longer functions but leaves traces. A geometric boundary uses straight lines or arcs. Some boundaries fit more than one label.",pic:scene('Six boundary types',d=>{for(const [x,y,t,e,col] of [[50,76,'Antecedent','before settlement',0],[235,76,'Subsequent','after settlement',1],[420,76,'Consequent','follows culture',2],[50,150,'Superimposed','imposed from outside',3],[235,150,'Relic','no longer in force',0],[420,150,'Geometric','straight lines, arcs',1]]){d.box(x,y,170,60,col);d.note(x+85,y+22,t,col);d.note(x+85,y+44,e,col);}d.note(320,236,'Classified by when and how they were drawn',3);})},
 {skill:"defining",say:"The UN Convention on the Law of the Sea (UNCLOS) sets maritime zones measured from a coastal state's baseline. A state may claim a territorial sea up to 12 nautical miles, where foreign ships keep the right of innocent passage. A contiguous zone reaches up to 24 nautical miles for customs and immigration enforcement. An exclusive economic zone (EEZ) extends up to 200 nautical miles and gives the state rights over fish and minerals. Beyond it lie the high seas. This drawing is to scale.",pic:scene('Maritime zones to scale (nautical miles)',d=>{d.box(50,100,28,50,3);d.note(62,125,'Land',3);d.box(78,100,26,50,0);d.box(104,100,27,50,1);d.box(131,100,387,50,2);d.box(518,100,72,50,3);d.note(100,82,'Territorial sea: 12',0);d.line(91,100,95,88,0,0,false,1);d.note(135,176,'Contiguous zone: 24',1);d.line(118,150,130,164,1,0,false,1);d.note(325,125,'Exclusive economic zone: 200',2);d.note(554,125,'High seas',3);d.note(78,200,'0');d.note(104,200,'12');d.note(131,200,'24');d.note(518,200,'200');d.note(320,232,'distance from the coast in nautical miles',3);})},
 {skill:"defining",say:"A nautical mile is 1.852 kilometers, so a distance in nautical miles is multiplied by 1.852 to give kilometers. The 12 nautical miles of the territorial sea come to 22.224 kilometers, the 24 of the contiguous zone to 44.448, and the 200 of the EEZ to 370.4. Convert first, then compare; nautical miles come from the length of an arc of latitude, which is why sailors and pilots use them.",eq:"km = nautical miles × 1.852",pic:board('Maritime zones in kilometers',['1 nautical mile = 1.852 km','Territorial sea: 12 × 1.852 = 22.224 km','Contiguous zone: 24 × 1.852 = 44.448 km','EEZ: 200 × 1.852 = 370.4 km']),
  check:{prompt:tryIt(TRY[1]),answer:55.56,options:[55.56,16.2,30],hint:'Multiply 30 by 1.852.',pic:tab('A fictional coast',[['claim','30 nautical miles'],['1 nautical mile','1.852 km']])}},
 {skill:"function",say:"Political boundaries mark where one state's sovereignty ends, and they let states control the movement of people, goods and ideas through customs and immigration checks. Some borders are open, as in much of Europe's Schengen Area, where passport checks have largely been removed; others are tightly controlled. Boundary disputes are often grouped as definitional, locational, operational or allocational. An enclave is territory surrounded by another state; an exclave is a part separated from its state's main territory.",pic:board('What boundaries do',['They mark where a state\'s sovereignty ends','They control people, goods and ideas at crossings','Open borders: few checks, as in much of the Schengen Area','Disputes: definitional, locational, operational, allocational','Enclave: surrounded; exclave: separated part'])},
 {skill:"internal",say:"Internal boundaries divide a state into provinces, counties, school districts and electoral districts. After a census, seats may be reapportioned among regions, and district lines are redrawn within them by redistricting. The principle of one person, one vote asks for districts of about equal population. Gerrymandering is drawing districts to favor a party or group. Cracking splits a group across districts so it is a minority in each; packing piles a group into one district so its votes are wasted elsewhere.",pic:board('Internal boundaries and districting',['Internal boundaries: provinces, counties, districts','Census → reapportionment (seats) → redistricting (lines)','One person, one vote: about equal population','Gerrymandering: lines drawn to favor a party or group','Cracking splits a group; packing piles it in one district'])},
 {skill:"internal",say:"A fictional state has 5 districts of 100 voters, and Party Orange wins exactly 250 of the 500 votes, which is 50 percent. If Orange's votes fall as 60, 60, 60, 35 and 35 it wins 3 districts. If the map packs 90 Orange votes into District 1 and cracks the rest as 40 in each of the other four, Orange wins only 1 district with the same 250 votes. The map, not the voters, changed the seats.",eq:"seats = districts with more than half the votes",pic:{t:'chart',kind:'bars',title:'Fictional map B: Orange votes in each district of 100',bars:[{label:'D1',value:90},{label:'D2',value:40},{label:'D3',value:40},{label:'D4',value:40},{label:'D5',value:40}]}},
 {skill:"governance",say:"States organize power in different ways. In a unitary state the central government holds most power, and local governments have only the powers it gives them; France is a usual example. In a federal state power is divided between a national government and regional governments, each with its own powers; the United States, Germany, India and Nigeria are federal. Federalism often suits large or diverse countries because regions can manage some of their own affairs.",pic:scene('Unitary and federal states (schematic)',d=>{d.note(165,70,'Unitary',0);d.box(95,84,140,34,0);d.note(165,101,'Central government',0);for(const x of [60,130,200]){d.box(x,160,70,34,1);d.note(x+35,177,'Local',1);d.line(165,120,x+35,158,3,1,false,1);}d.note(165,216,'powers are delegated',3);d.note(465,70,'Federal',1);d.box(360,84,100,34,0);d.note(410,101,'National',0);d.box(480,84,100,34,1);d.note(530,101,'Regional',1);d.line(462,96,478,96,3);d.line(462,106,478,106,3);d.note(470,176,'each level holds its own powers',3);d.note(470,198,'set by a constitution',3);}),
  check:{prompt:tryIt(TRY[2]),answer:'federal',options:['federal','unitary','autocracy'],hint:'Power is divided between two levels, and neither can remove the other\'s powers.',pic:tab('The case',[['national government','has its own powers'],['regional governments','have their own powers']])}},
 {skill:"devolution",say:"Devolution is the transfer of power from a central government to regional or local governments. Geographers list several factors that can push power away from the center. Physical geography, such as islands or mountains, can separate regions from the capital. Ethnic separatism is a group's wish for more self-rule or independence. Economic and social differences between regions can cause resentment. Irredentism is a state's claim to territory in a neighbor based on shared ethnicity or history, and terrorism can also strain a state.",pic:scene('Factors that can promote devolution',d=>{for(const [x,y,t,e,col] of [[50,76,'Physical geography','islands, mountains',0],[235,76,'Ethnic separatism','seeks self-rule',1],[420,76,'Economic differences','unequal regions',2],[142,150,'Irredentism','claims across a border',3],[327,150,'Terrorism','violence to coerce',0]]){d.box(x,y,170,52,col);d.note(x+85,y+19,t,col);d.note(x+85,y+39,e,col);}d.note(320,236,'Forces that can push power away from the center',3);})},
 {skill:"devolution",say:"Devolution and breakup have taken different forms. The Soviet Union dissolved in 1991 into independent republics. Yugoslavia began to break up in 1991, and the breakup came with wars through the 1990s. Czechoslovakia split into two states in 1993 by agreement. The United Kingdom set up a Scottish Parliament in 1999, an example of devolution without separation. Similar debates over autonomy continue in places such as Catalonia in Spain.",pic:{t:'timeline',events:['Soviet Union dissolves, 1991','Yugoslavia begins to break up, 1991','Czechoslovakia splits by agreement, 1993','Scottish Parliament set up in the UK, 1999']}},
 {skill:"sovereignty",say:"Supranational organizations are groups of states that agree to share some authority to pursue common goals, so membership can limit a state's independence. The United Nations, founded in 1945, is global. The European Union is a political and economic union in Europe. ASEAN, founded in 1967, links Southeast Asian states, and the African Union, launched in 2002, links African states. Trade blocs, global media, transnational corporations, separatist movements and terrorism can also challenge sovereignty.",pic:scene('Four supranational organizations',d=>{for(const [x,y,t,e,col] of [[60,82,'United Nations','global, founded 1945',0],[340,82,'European Union','Europe, shared rules',1],[60,166,'ASEAN','Southeast Asia, 1967',2],[340,166,'African Union','Africa, launched 2002',3]]){d.box(x,y,230,60,col);d.note(x+115,y+22,t,col);d.note(x+115,y+44,e,col);}})},
 {skill:"forces",say:"Centripetal forces unite people and hold a state together: a shared national identity, symbols and holidays, a common language, transport links and a government seen as fair. Centrifugal forces divide a state: ethnic or religious conflict, deep regional inequality, separatist movements and weak institutions. Federalism, which gives regions some self-rule, can ease centrifugal pressure. Which force wins varies by place and time.",pic:scene('Two kinds of force on a state',d=>{d.note(170,70,'Centripetal',0);d.circle(170,135,26,0);d.note(170,135,'State',0);for(const [a,b,c,e] of [[170,90,170,108],[170,180,170,162],[100,135,142,135],[240,135,198,135]])d.line(a,b,c,e,0,1,false,2);d.note(170,206,'unite: identity, roads, fairness',0);d.note(470,70,'Centrifugal',1);d.circle(470,135,26,1);d.note(470,135,'State',1);for(const [a,b,c,e] of [[470,110,470,92],[470,160,470,178],[444,135,402,135],[496,135,538,135]])d.line(a,b,c,e,1,1,false,2);d.note(470,206,'divide: rivalry, inequality',1);d.note(320,236,'Arrows show the direction of pull',3);}),
  check:{prompt:tryIt(TRY[3]),answer:'centrifugal',options:['centrifugal','centripetal','irredentist'],hint:'A demand to separate pulls the state apart.',pic:tab('The case',[['province','ignored for decades'],['demand','separation']])}},
 {skill:"forces",summary:true,say:"Tie the unit together by reading a state in four questions. What is the state, and is it a nation-state or multinational? How were its boundaries drawn, and what do they control? How is power organized inside it, unitary or federal, and how are districts drawn? Which centripetal and centrifugal forces, devolution pressures and supranational ties act on it? Describe disputes neutrally and note that most places show several forces at once.",pic:scene('Unit 4: reading a state',d=>{for(const [x,a,b,col] of [[50,'Define','state, nation',0],[195,'Bound','type and zones',1],[340,'Govern','unitary, federal',2],[485,'Balance','unite or divide',3]]){d.box(x,104,110,56,col);d.note(x+55,125,a,col);d.note(x+55,146,b,col);}for(const x of [162,307,452])d.line(x,132,x+30,132,3,1);d.note(320,222,'Define, bound, govern, then weigh the forces',3);})}],
progression:{requires:['geography-h-ap-hug-cultural-patterns-and-processes'],operations:1,demand:'Sort states, nations, boundary types, disputes and forms of government by their definitions, convert nautical miles to kilometers at 1.852, count the districts a party wins from fictional vote tallies, and tell centripetal from centrifugal forces and devolutionary factors.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 const ask=(skill,rows,pic,k0=0)=>rows.forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+k0);put(skill,`${q} ${c.text}. Answer A, B or C.`,c.letter,pic,why||`The answer is ${right}.`,[right]);});
 const sort=(skill,rows,ask2,names,pic)=>rows.forEach(([s,k])=>put(skill,`${s} ${ask2}`,k,tab(pic,[['case',s]],['']),names[k]));
 const win=(sz,v)=>v.filter(x=>x>sz/2).length;
 /* intro */
 ask('intro',[['What is a state in political geography?','a political unit with defined territory, a permanent population, a government and sovereignty',['a group of people who share a culture and a sense of identity','a region defined only by its climate'],'A state is a political unit with defined territory, a permanent population, a government and sovereignty. A group sharing a culture is a nation.'],
  ['What is a nation?','a group of people who share a culture, history and sense of identity, whether or not they have their own state',['a political unit with a government and defined borders','a country where only one language is allowed by law'],'A nation is a group with a shared culture, history and identity. It may or may not have its own state; a state is the political unit.'],
  ['What is a nation-state?','a state whose territory is occupied largely by a single nation',['a state that contains several nations','a nation that has no state'],'A nation-state is a state whose territory is home mostly to one nation, so political borders and national identity largely match.'],
  ['What is a multinational state?','a state that contains more than one nation',['a nation divided among several states','a state with only one nation'],'A multinational state contains two or more nations within its borders, such as Nigeria or the United Kingdom.'],
  ['What is a multistate nation?','a nation that stretches across the borders of more than one state',['a state that contains several nations','a nation that has no territory'],'A multistate nation is one nation whose people live across the borders of more than one state, such as Koreans in North and South Korea.'],
  ['What is a stateless nation?','a nation that has no state of its own',['a state that has lost its government','a nation that controls several states'],'A stateless nation is a people with a shared identity but no state of its own, such as the Kurds or Palestinians.'],
  ['What is sovereignty?','a state\'s supreme authority to govern its territory without outside control, recognized by other states',['a state\'s right to rule other countries','the total wealth of a state'],'Sovereignty is a state\'s supreme authority to govern its own territory without outside control, recognized by other states.'],
  ['What is self-determination?','the principle that a people has the right to decide its own political status and government',['the right of a state to take over a neighbor','the practice of drawing boundaries along straight lines'],'Self-determination is the principle that a people may choose its own political status and government, which can include independence.'],
  ['Which people is often cited as a stateless nation, living mainly in parts of Turkey, Iraq, Iran and Syria?','the Kurds',['the Icelanders','the Swiss'],'The Kurds, tens of millions of people, live mainly across Turkey, Iraq, Iran and Syria without a state of their own, so they are a stateless nation.'],
  ['Which country is often cited as multinational because it contains hundreds of ethnic groups with different languages?','Nigeria',['Iceland','Japan'],'Nigeria has hundreds of ethnic groups and languages, such as Hausa, Yoruba and Igbo, within one state, so it is multinational.'],
  ['Which country is often cited as close to a nation-state because most of its people share one national identity?','Iceland',['Nigeria','India'],'Most of Iceland\'s small population shares one language, history and identity, so it is often cited as close to a nation-state.'],
  ['Which term describes a people with a shared identity who live mainly in two neighboring states, as Koreans do in North and South Korea?','multistate nation',['stateless nation','nation-state'],'Koreans share a nation but live in two states, North and South Korea, which makes them a multistate nation.'],
  ['Why are few countries pure nation-states?','most states contain more than one ethnic or cultural group',['states cannot have a government','every nation lives in several states'],'Most states contain more than one ethnic or cultural group, so few match the pure nation-state ideal of one nation, one state.'],
  ['Which feature belongs to the usual definition of a state but not of a nation?','sovereignty over a defined territory',['a shared culture','a shared sense of identity'],'Sovereignty over a defined territory is part of the definition of a state. Shared culture and identity define a nation.'],
  ['What does political geography study?','how political power and boundaries are organized across space and how places shape politics',['only the weather in capital cities','the spelling of place names'],'Political geography studies how power and boundaries are organized across space, and how places and territory shape politics.']],tab('Political geography',[['state','territory and sovereignty'],['nation','shared identity'],['nation-state','the two coincide']],['Idea']));
 sort('intro',NATION,'Which term fits best: nation-state, multinational state or stateless nation?',{'nation-state':'The state and one nation largely coincide: a nation-state.','multinational state':'The state holds more than one nation: a multinational state.','stateless nation':'The nation has no state of its own: a stateless nation.'},'State and nation');
 /* processes */
 ask('processes',[['Which description fits colonialism as a political process?','a state taking control of a territory, often settling it and governing its people for its own benefit',['a trade agreement between equal partners','a treaty drawing a boundary along a river'],'Colonialism is a state taking control of a territory, often settling it and ruling its people mainly for the colonial power\'s benefit.'],
  ['Which description fits imperialism?','a policy of extending a state\'s power and influence over other territories or peoples, by force, treaty or economic control',['the division of a state into smaller units','a union of states with equal power'],'Imperialism is the broad policy of extending power over other lands or peoples, by force, treaty or economic control.'],
  ['How do many geographers distinguish colonialism from imperialism?','colonialism involves direct control and settlement of territory, while imperialism is the wider policy of extending power, which may be indirect',['they are always identical in every case','imperialism only occurs inside a state\'s own borders'],'Many geographers use colonialism for direct rule and settlement, and imperialism for the wider policy of extending power, which may be indirect.'],
  ['What is neocolonialism?','continued economic, political or cultural influence by powerful states over formerly colonized places, without formal rule',['the founding of a brand-new colony with settlers','the end of all trade between countries'],'Neocolonialism is continued economic, political or cultural control by powerful states over former colonies after formal rule has ended.'],
  ['What is decolonization?','the process by which colonies gained independence from colonial rule',['the founding of new colonies','the drawing of straight-line boundaries'],'Decolonization is the process by which colonies gained independence and ended colonial rule.'],
  ['When did the largest wave of decolonization take place?','the decades after World War II, especially the 1950s and 1960s',['the 1400s','the 2000s'],'The largest wave of decolonization came after World War II, especially in the 1950s and 1960s, when most of Africa and Asia gained independence.'],
  ['What was the Berlin Conference of 1884-85?','a meeting at which European powers set rules for claiming African territory, without African rulers at the table',['a treaty that ended the Cold War','a conference that created the United Nations'],'At the Berlin Conference, European powers set rules for claiming African land. No African rulers were present.'],
  ['Which motives are often summarized as "God, gold and glory"?','spreading religion, gaining wealth and gaining power and prestige',['farming, fishing and fuel','language, law and literature'],'God, gold and glory sums up common motives for European expansion: spreading Christianity, gaining wealth and winning power and prestige.'],
  ['Why did many boundaries drawn by colonial powers cause later conflict?','they often split ethnic groups and joined groups who had little shared identity',['they always followed ethnic homelands exactly','they were drawn by the colonized peoples themselves'],'Colonial borders were often drawn with little regard for local peoples, splitting some ethnic groups and joining rivals, which fed later conflict.'],
  ['What is a colony?','a territory controlled by another state, called the colonial power',['a self-governing state with full sovereignty','a nation with no territory'],'A colony is a territory controlled and governed by another state, the colonial power. It lacks full sovereignty.'],
  ['How did the number of independent states change after 1945?','it grew greatly as former colonies became independent',['it fell sharply','it did not change'],'As colonies gained independence after 1945, the number of independent states grew greatly, from about 50 UN founders to over 190 today.'],
  ['The Peace of Westphalia (1648) is often cited as the origin of which idea?','the modern idea of sovereign states with defined territory',['the Cold War','the euro'],'The Peace of Westphalia ended the Thirty Years\' War in 1648. It is often cited as the origin of sovereign states with defined territory.'],
  ['What did the Scramble for Africa describe?','the rapid claiming of most of Africa by European powers in the late 1800s',['the spread of the telegraph across Europe','the independence of African states in the 1960s'],'The Scramble for Africa was the rush by European powers to claim most of Africa in the late 1800s, roughly 1880 to 1914.']],tab('Political processes',[['colonialism','direct control and settlement'],['imperialism','extending power'],['decolonization','independence']],['Idea']));
 /* power */
 ask('power',[['What is territoriality?','the attempt by a person, group or state to claim, control and defend an area',['the study of climate zones','the spread of a language'],'Territoriality is when people or states claim, control and defend an area, such as a state guarding its borders.'],
  ['What is geopolitics?','the study of how geography shapes the power, politics and strategy of states',['the study of voting methods only','the study of rocks and minerals'],'Geopolitics studies how geography, such as location, size and resources, shapes the power and strategy of states.'],
  ['What did Mackinder\'s Heartland theory argue?','that control of the interior of Eurasia, the Heartland, could give a state world power',['that sea power alone was the key to world power','that borders do not affect power'],'Mackinder argued in 1904 that whoever controlled the Heartland, the interior of Eurasia, could dominate the world.'],
  ['Spykman\'s Rimland theory stressed control of which area?','the coastal edge of Eurasia, the Rimland',['the interior of Africa','the polar regions'],'Spykman argued that the Rimland, the coastal edge of Eurasia, was the key to world power, not the Heartland.'],
  ['What was the domino theory in the Cold War?','the idea held by some US leaders that if one state fell to communism, its neighbors would follow',['the idea that trade barriers fall in a chain','the idea that all states would become democracies at once'],'Some U.S. Cold War leaders believed that if one country fell to communism, its neighbors would fall in turn, like dominoes.'],
  ['What is a balance of power?','a situation in which power is spread among states so that no single state dominates',['a situation where one state rules all others','an equal division of population among districts'],'A balance of power spreads power among states so no single one dominates, which can discourage any state from attacking.'],
  ['Which two alliances faced each other in Europe during the Cold War?','NATO and the Warsaw Pact',['the EU and ASEAN','the African Union and the Arab League'],'NATO, led by the United States, faced the Soviet-led Warsaw Pact in Europe during the Cold War. ASEAN and the AU are other regions.'],
  ['Which is an example of political power at the local scale?','a city council deciding zoning',['a treaty among many nations','a vote of the UN Security Council'],'A city council deciding zoning is power at the local scale. Treaties and Security Council votes act at the international scale.'],
  ['Which is an example of a state exercising territoriality?','building border posts and enforcing its laws within its borders',['choosing a new national dish','forecasting the weather'],'Border posts and enforcing its laws at home show a state claiming, controlling and defending its territory: territoriality.'],
  ['What is a buffer state?','a small or weaker state lying between two rival powers that reduces the chance of direct conflict',['a state that has no borders','a state that rules its neighbors'],'A buffer state sits between rival powers and keeps them apart, reducing the chance they clash directly.'],
  ['What is the usual role of a capital city?','it is the seat of the national government',['it is always the largest city','it is always on the coast'],'A capital is the seat of the national government. It is not always the largest city or on the coast, such as Canberra or Brasília.']],tab('Political power',[['territoriality','claiming and defending an area'],['geopolitics','geography and power'],['theories','Heartland, Rimland, domino']],['Idea']));
 /* defining */
 ask('defining',[['What is an antecedent boundary?','a boundary drawn before an area is heavily settled',['a boundary drawn along a line of latitude or longitude','a boundary that once existed and has left traces'],'An antecedent boundary is drawn before an area is heavily settled, such as much of the U.S.-Canada border in the West.'],
  ['What is a subsequent boundary?','a boundary drawn after an area has been settled, which may be adjusted as conditions change',['a boundary drawn before anyone has settled','a boundary that is a straight line on a map'],'A subsequent boundary is drawn after an area is settled, and it may be adjusted as conditions change.'],
  ['What is a consequent boundary?','a boundary drawn to follow cultural differences such as language or religion',['a boundary drawn before settlement','a straight line with no regard for culture'],'A consequent boundary is drawn to follow cultural differences, such as language or religion, to separate groups.'],
  ['What is a superimposed boundary?','a boundary imposed by outside powers on an area, ignoring existing cultural patterns',['a boundary that follows a river','a boundary that follows language groups'],'A superimposed boundary is imposed by outside powers, ignoring existing cultures, as with many colonial borders in Africa.'],
  ['What is a relic boundary?','a boundary that no longer functions as a border but whose traces remain on the landscape',['a boundary drawn along parallels of latitude','a boundary between two oceans'],'A relic boundary no longer works as a border but leaves traces on the landscape, such as Hadrian\'s Wall or remains of the Berlin Wall.'],
  ['What is a geometric boundary?','a boundary drawn as straight lines or arcs, such as along parallels or meridians',['a boundary that follows a mountain ridge','a boundary that follows a language group'],'A geometric boundary is a straight line or arc, often along a parallel or meridian, like the 49th parallel between the U.S. and Canada.'],
  ['Which is a physical (natural) boundary?','a river or a mountain range',['a difference in language between peoples','a straight line of latitude'],'A physical boundary follows a natural feature, such as a river or a mountain range. A language divide is a cultural boundary.'],
  ['Which is a cultural boundary?','a border that follows a difference of language or religion',['a mountain crest','a river channel'],'A cultural boundary follows a difference between peoples, such as language or religion. Mountains and rivers are physical boundaries.'],
  ['In making a boundary, what is delimitation?','drawing the boundary on a map',['marking the boundary on the ground with posts or walls','writing the boundary into a treaty in words'],'Delimitation is drawing the boundary on a map. Marking it on the ground with posts or fences is demarcation.'],
  ['In making a boundary, what is demarcation?','marking the boundary on the ground with posts, fences or walls',['drawing the boundary on a map','writing the boundary into a treaty in words'],'Demarcation is marking a boundary on the ground with posts, fences or walls. Drawing it on a map is delimitation.'],
  ['Under UNCLOS, how far from its baseline can a state claim a territorial sea?','up to 12 nautical miles',['up to 3 nautical miles','up to 200 nautical miles'],'Under UNCLOS, a state\'s territorial sea extends up to 12 nautical miles from its baseline, and the state is sovereign there.'],
  ['Under UNCLOS, how far from its baseline may a state claim an exclusive economic zone (EEZ)?','up to 200 nautical miles',['up to 12 nautical miles','up to 24 nautical miles'],'Under UNCLOS, a state may claim an exclusive economic zone up to 200 nautical miles from its baseline.'],
  ['What rights does a state have in its EEZ?','sovereign rights over living and mineral resources, such as fish and oil, while other ships keep freedom of navigation',['complete sovereignty over everything, including the right to block all foreign ships','no rights over any resources'],'In its EEZ a state controls resources like fish, oil and gas, but other states\' ships keep freedom of navigation there.'],
  ['What is the right of innocent passage?','foreign ships may pass through a state\'s territorial sea if they do not threaten its peace or security',['foreign ships may fish freely there','foreign ships may never enter a territorial sea'],'Innocent passage lets foreign ships cross a state\'s territorial sea if they do not threaten its peace, good order or security.'],
  ['What are the high seas?','waters beyond any state\'s EEZ, open to all states',['the area inside a state\'s territorial sea','a state\'s internal rivers'],'The high seas are waters beyond any state\'s EEZ. They are open to all states for navigation and fishing, within international law.'],
  ['What is the contiguous zone under UNCLOS?','a zone up to 24 nautical miles from the baseline where a state may enforce customs and immigration laws',['the zone out to 200 nautical miles with all resources','the zone of a state\'s inland rivers'],'The contiguous zone reaches up to 24 nautical miles from the baseline. There a state can enforce customs, immigration and health laws.'],
  ['What does UNCLOS stand for?','the United Nations Convention on the Law of the Sea',['the United Nations Council on Land Surveys','the Union of Northern Coastal States'],'UNCLOS is the United Nations Convention on the Law of the Sea, a treaty agreed in 1982 that sets rules for the world\'s seas.'],
  ['How many kilometers are in one nautical mile?','1.852 kilometers',['1.609 kilometers','1 kilometer'],'One nautical mile is defined as exactly 1.852 kilometers. A land (statute) mile is about 1.609 kilometers.']],tab('Boundaries',[['antecedent','before settlement'],['consequent','follows culture'],['EEZ','up to 200 nautical miles']],['Idea']),1);
 sort('defining',BOUND,'Which boundary type fits best: antecedent, subsequent, consequent, superimposed, relic or geometric?',{antecedent:'It was drawn before settlement: antecedent.',geometric:'It is a straight line or arc: geometric.',consequent:'It follows cultural differences: consequent.',superimposed:'Outside powers imposed it, ignoring local groups: superimposed.',relic:'It no longer functions but leaves traces: relic.',subsequent:'It was drawn after settlement and later adjusted: subsequent.'},'Boundary type');
 for(const v of [100,50,35,150,20]){const k=r4(v*1.852);put('defining',`A fictional ship is ${v} nautical miles from a coast. How many kilometers is that? Use 1 nautical mile = 1.852 kilometers.`,k,tab('A fictional ship',[['distance',`${v} nautical miles`],['1 nautical mile','1.852 km']]),`${v} × 1.852 = ${pct(k)} km.`);}
 for(const km of [18.52,74.08,111.12]){const v=r4(km/1.852);put('defining',`A fictional patrol boat is ${km} kilometers from a coast. How many nautical miles is that? Use 1 nautical mile = 1.852 kilometers.`,v,tab('A fictional boat',[['distance',`${km} km`],['1 nautical mile','1.852 km']]),`${km} ÷ 1.852 = ${pct(v)} nautical miles.`);}
 put('defining','How many kilometers wide is the band from the outer edge of a 12-nautical-mile territorial sea to the outer edge of a 200-nautical-mile EEZ? Use 1 nautical mile = 1.852 kilometers.',r4(188*1.852),tab('The band',[['inner edge','12 nautical miles'],['outer edge','200 nautical miles']]),'(200 - 12) × 1.852 = 348.176 km.');
 /* function */
 ask('function',[['What main functions do political boundaries serve?','they mark where a state\'s sovereignty begins and ends and help control the movement of people and goods',['they mark climate zones','they show exactly where languages change'],'Boundaries mark where a state\'s sovereignty begins and ends, and states use them to control who and what crosses.'],
  ['What is an open border?','a border with few or no controls on crossing, as among many Schengen Area countries',['a border closed to all movement by a wall','a border that moves with a river each year'],'An open border has few or no controls on crossing. Within the Schengen Area, most travel between member countries has no routine passport checks.'],
  ['What is the Schengen Area?','a group of European countries that have largely removed passport checks at their shared borders',['a military alliance of Asian countries','a currency used only by Pacific islands'],'The Schengen Area is a group of European countries that have largely removed passport checks at their shared borders.'],
  ['What is an enclave?','a territory entirely surrounded by the territory of another state',['a piece of a state separated from its main part','a state without a coast'],'An enclave is completely surrounded by another state, like Lesotho inside South Africa or Vatican City inside Italy.'],
  ['What is an exclave?','a part of a state that is separated from the main territory by another state\'s land or water',['a territory entirely surrounded by another state','a state with no neighbors'],'An exclave is part of a state cut off from the main territory by another state\'s land or water, such as Russia\'s Kaliningrad.'],
  ['What is a landlocked state?','a state with no coastline on an ocean or sea',['a state made up of islands','a state whose capital is on the coast'],'A landlocked state has no coastline on an ocean or sea, such as Bolivia or Switzerland, so it depends on neighbors for sea trade.'],
  ['Why might a state build a fence or wall along part of a border?','to control the movement of people and goods or to protect security, though people differ on how well it works',['to change the climate','to measure the border'],'States build barriers to control movement of people and goods or for security. How well walls work is debated.'],
  ['What is a customs check at a border?','an inspection of goods and travelers entering a state, where duties may be collected',['a vote on where the border belongs','a map showing the border'],'At a customs check, officials inspect goods and travelers entering a state and may collect duties, or taxes, on imports.'],
  ['How can a boundary lead to cooperation?','neighbors can sign agreements on trade, shared rivers, policing and travel',['boundaries make agreements impossible','boundaries are never negotiated'],'Neighbors can sign agreements on trade, shared rivers, policing and travel, so a boundary can be a place of cooperation.'],
  ['Why can rivers be difficult as boundaries?','rivers can shift course, so the border line may be disputed',['rivers are always straight lines','rivers never flow between countries'],'Rivers can shift their course over time, so a border that follows a river can become unclear and disputed.'],
  ['What is a boundary dispute?','a disagreement between states over where a border lies, how it works or who uses its resources',['an agreement to remove a border','a vote inside one state about its flag'],'A boundary dispute is a disagreement over where a border lies, how it works, or who uses resources along it.']],tab('Boundary functions',[['separate','where sovereignty ends'],['control','people and goods'],['cooperate','trade and shared rivers']],['Idea']));
 sort('function',DISPUTE,'Which kind of boundary dispute is this: definitional, locational, operational or allocational?',{definitional:'It is about what the words of a boundary agreement mean: definitional.',locational:'It is about where the line should be marked on the ground: locational.',operational:'It is about how the border works in practice: operational.',allocational:'It is about who gets the resources near the border: allocational.'},'Dispute');
 /* internal */
 ask('internal',[['What is an internal boundary?','a boundary inside a state, such as a province, county or electoral district line',['the boundary between two countries','a line of latitude on a globe'],'An internal boundary divides areas inside one state, such as provinces, counties or electoral districts.'],
  ['What is redistricting?','redrawing the boundaries of electoral districts',['moving a capital city','counting the population'],'Redistricting is redrawing the boundaries of electoral districts, often after a census shows population changes.'],
  ['What is reapportionment?','reallocating legislative seats among regions after a census, based on changes in population',['redrawing district lines within a state','electing a new head of state'],'Reapportionment shares out legislative seats among regions, such as U.S. House seats among states, after a census.'],
  ['How often is the United States census taken, prompting reapportionment and redistricting?','every 10 years',['every 2 years','every 25 years'],'The U.S. Constitution requires a census every 10 years. The results drive reapportionment of House seats and redistricting.'],
  ['In political geography, what does gerrymandering mean?','drawing electoral district boundaries to give one party or group an advantage',['counting votes by hand','making districts exactly equal in population'],'Gerrymandering is drawing district lines to give one party or group an advantage in elections.'],
  ['What is cracking in gerrymandering?','splitting a group of like-minded voters across several districts so they cannot form a majority in any',['concentrating a group of voters into one district','making districts equal in size'],'Cracking splits a group\'s voters across many districts so they are a minority everywhere and cannot win any seat.'],
  ['What is packing in gerrymandering?','concentrating many of a group\'s voters into one district so their influence is lost in the others',['splitting a group across many districts','counting each vote twice'],'Packing crowds a group\'s voters into one district, so they win it by a huge margin but have little influence elsewhere.'],
  ['The word gerrymander is associated with which governor and which year?','Elbridge Gerry of Massachusetts and 1812',['Thomas Jefferson and 1776','Abraham Lincoln and 1860'],'The term comes from Massachusetts governor Elbridge Gerry, who signed an 1812 district map with one district said to look like a salamander.'],
  ['What does "one person, one vote" require of district maps?','that districts for the same legislature have about equal populations',['that every district be a perfect square','that every district elect the same party'],'One person, one vote means districts for the same body must have about equal populations, so each vote counts about the same.'],
  ['What is a majority-minority district?','a district in which a racial or ethnic minority group makes up the majority of the population',['a district where minorities cannot vote','a district with no residents'],'In a majority-minority district, a group that is a minority statewide, such as a racial or ethnic group, makes up the district\'s majority.'],
  ['Which feature is often examined as a possible sign of gerrymandering?','an oddly shaped, non-compact district',['a district with a regular, compact shape','a district drawn after an equal-population count'],'Odd, sprawling or non-compact shapes can be a sign that lines were drawn to include or exclude certain voters, though shape alone is not proof.'],
  ['Which body is used in some states to draw districts with less partisan influence?','an independent redistricting commission',['the president alone','the United Nations'],'An independent redistricting commission draws district maps in some states, aiming to reduce partisan influence.'],
  ['Which are examples of internal boundaries other than electoral districts?','school districts, counties and city limits',['oceans, deserts and mountains','the borders of other countries'],'School districts, counties and city limits are internal boundaries inside a state. Oceans and deserts are natural features.']],tab('Internal boundaries',[['reapportionment','seats among regions'],['redistricting','district lines'],['gerrymandering','lines drawn for advantage']],['Idea']));
 sort('internal',GERRY,'Is this cracking or packing?',{cracking:'The group is split so it is a minority everywhere: cracking.',packing:'The group is piled into one district: packing.'},'Gerrymandering');
 for(const [k,sz,v] of SEATS){const w=win(sz,v);put('internal',`A fictional state has ${k} districts of ${sz} voters each. Party Orange gets ${list(v)} votes in Districts 1 to ${k}, and Party Teal gets the rest. How many districts does Orange win? A district goes to the party with more than half of its votes.`,w,tab('A fictional state',[['districts',`${k} of ${sz} voters`],['Orange votes',v.join(', ')]]),`Orange has more than ${sz/2} votes in ${w} districts.`);}
 for(const i of [0,2,3]){const [k,sz,v]=SEATS[i],s=v.reduce((a,b)=>a+b,0),p=s/(k*sz)*100;put('internal',`A fictional state has ${k} districts of ${sz} voters each. Party Orange gets ${list(v)} votes in Districts 1 to ${k}, and Party Teal gets the rest. What percent of all votes cast does Orange receive?`,p,tab('A fictional state',[['districts',`${k} of ${sz} voters`],['Orange votes',v.join(', ')]]),`${s} ÷ ${k*sz} × 100 = ${pct(p)}%.`);}
 for(const [a,b,v] of [[4,5,52],[7,10,55],[5,8,48]]){const d=r4(a/b*100-v);put('internal',`A fictional party wins ${a} of ${b} districts with ${v} percent of all votes. By how many percentage points is its share of the seats larger than its share of the votes?`,d,tab('A fictional party',[['seats',`${a} of ${b}`],['votes',`${v}%`]]),`${a} ÷ ${b} × 100 = ${pct(a/b*100)}%, and ${pct(a/b*100)} - ${v} = ${pct(d)} points.`);}
 for(const [p,k] of [[900000,6],[3600000,9],[2100000,7]])put('internal',`A fictional state with a population of ${n(p)} is divided into ${k} districts of equal population. How many people does each district have?`,p/k,tab('A fictional state',[['population',n(p)],['districts',`${k}`]]),`${n(p)} ÷ ${k} = ${n(p/k)} people.`);
 /* governance */
 ask('governance',[['What is a unitary state?','a state in which the central government holds most power and local governments have only the powers it gives them',['a state in which power is constitutionally divided between national and regional governments','a loose union in which members keep full sovereignty'],'In a unitary state, the central government holds most power, and local governments have only the powers it grants them.'],
  ['What is a federal state?','a state in which power is divided between a national government and regional governments, each with its own powers',['a state where all power is held by the central government','a state with no government'],'In a federal state, a constitution divides power between the national government and regional governments like states or provinces.'],
  ['Which of these countries is usually classed as a unitary state?','France',['Germany','Nigeria'],'France is usually classed as unitary, with power centered in Paris. Germany and Nigeria are federal states.'],
  ['Which of these countries is a federal state?','India',['Japan','Egypt'],'India is a federal republic with states that have their own governments. Japan and Egypt are unitary states.'],
  ['Why do many large or diverse countries choose federalism?','it lets regions with different identities manage some of their own affairs',['it removes all regional differences','it requires one language by law'],'Federalism lets regions with different identities, languages or needs manage some of their own affairs, which can hold a diverse country together.'],
  ['What is a democracy?','a form of government in which power rests with the people, who choose leaders through elections',['a government in which one ruler holds power for life','a government run by religious leaders'],'In a democracy, power rests with the people, who choose leaders through elections. One ruler for life is autocracy.'],
  ['What is an autocracy?','a government in which one person holds nearly all power',['a government in which citizens elect leaders freely','a government with several equal regional governments'],'In an autocracy, one person holds nearly all power, without free elections or real limits.'],
  ['What is a theocracy?','a government in which religious leaders or religious law hold the highest authority',['a government in which only elected representatives hold power','a government in which a small group of wealthy people rules'],'In a theocracy, religious leaders or religious law hold the highest authority over government.'],
  ['What is a confederation?','a loose union of sovereign states that give a central body limited powers',['a single state with one central government','a nation with no territory'],'A confederation is a loose union of sovereign states that give a central body only limited powers.'],
  ['What is an oligarchy?','a government in which a small group holds power',['a government in which everyone votes directly on every law','a government in which a single monarch holds power for life'],'An oligarchy is rule by a small group, often defined by wealth, family or military power.'],
  ['In a federal state, who usually settles disputes over whether the national or a regional government holds a power?','a constitution interpreted by courts',['a vote of neighboring countries','the largest regional government alone'],'In a federal state, the constitution divides powers, and courts interpret it when national and regional governments disagree.']],tab('Forms of governance',[['unitary','central government holds power'],['federal','power divided by a constitution'],['democracy','power rests with the people']],['Idea']));
 sort('governance',GOV,'Is this a unitary or a federal state?',{unitary:'Power is held mainly by the national government: a unitary state.',federal:'Power is divided between national and regional governments: a federal state.'},'Governance');
 for(const [s,e] of [[6,2],[9,3],[5,4]])put('governance',`A fictional federation has ${s} states, and each state elects ${e} senators to the national senate. How many senators are there in total?`,s*e,tab('A fictional federation',[['states',`${s}`],['senators per state',`${e}`]]),`${s} × ${e} = ${s*e} senators.`);
 /* devolution */
 ask('devolution',[['In political geography, what does devolution mean?','the transfer of power from a central government to regional or local governments',['the union of several states under one government','a state taking over a neighbor'],'Devolution is when a central government transfers some power to regional or local governments.'],
  ['What is ethnic separatism?','the desire of an ethnic group to gain more self-rule or to separate from a state',['the policy of treating all groups exactly alike','a state\'s claim to a neighbor\'s land'],'Ethnic separatism is when an ethnic group seeks more self-rule or independence from the state it lives in.'],
  ['What is irredentism?','a state\'s claim to territory in a neighboring state based on shared ethnicity or history',['a region\'s demand for more local self-government','a group\'s decision to leave a country voluntarily'],'Irredentism is a state\'s claim to land in a neighboring state because people there share its ethnicity or history.'],
  ['Which physical-geography factor can encourage devolution?','islands or mountains that separate regions and weaken links to the capital',['a single flat plain with fast roads','a shared national language'],'Physical barriers like water or mountains can separate a region from the capital, weaken links and encourage demands for self-rule.'],
  ['How can economic differences promote devolution?','a wealthier region may resent sending tax revenue elsewhere, or a poorer region may feel neglected',['all regions always have equal incomes','economic differences cannot matter for politics'],'A richer region may resent paying for others, while a poorer region may feel neglected. Both feelings can fuel demands for devolution.'],
  ['Which group of factors do geographers often list as promoting devolution?','physical geography, ethnic separatism, economic and social problems, irredentism and terrorism',['a shared language, strong national symbols and even development','only a state\'s choice of national flag'],'Geographers often list physical geography, ethnic separatism, economic and social problems, irredentism and terrorism as forces promoting devolution.'],
  ['The Scottish Parliament has operated within the United Kingdom since which year?','1999',['1707','1945'],'The Scottish Parliament opened in 1999 after a 1997 referendum. 1707 is when Scotland\'s old parliament merged into Great Britain\'s.'],
  ['The Scottish Parliament set up in 1999 is an example of what process?','devolution',['irredentism','supranationalism'],'The UK gave Scotland its own parliament with power over areas like education and health. Moving power from the center is devolution.'],
  ['How did the end of Czechoslovakia in 1993 differ from the breakup of Yugoslavia in the 1990s?','Czechoslovakia split peacefully by agreement, while Yugoslavia\'s breakup involved wars',['both ended with no change in borders','Czechoslovakia broke up through a long war while Yugoslavia split peacefully'],'Czechoslovakia split into the Czech Republic and Slovakia peacefully in 1993, while Yugoslavia\'s breakup involved years of war.'],
  ['In which year did the Soviet Union dissolve?','1991',['1945','1989'],'The Soviet Union dissolved in December 1991 into 15 independent states. 1989 was the fall of the Berlin Wall.'],
  ['Which region of Spain has a long-running debate over autonomy and independence?','Catalonia',['Extremadura','Andalusia'],'Catalonia, in northeast Spain, has its own language and strong identity, and it has a long-running debate over autonomy and independence.'],
  ['What is an autonomous region?','a region with a degree of self-government within a larger state',['an independent member of the UN','a region with no local government'],'An autonomous region governs some of its own affairs, but remains part of a larger state. It is not an independent UN member.'],
  ['Which is a possible result of devolution?','a regional government gains control over matters such as education or health',['the national government gains all regional powers','a region\'s boundaries disappear'],'With devolution, regions gain powers such as education or health, while the national state keeps others, such as defense.']],tab('Devolution',[['devolution','power moves from the center'],['factors','geography, ethnicity, economy, irredentism, terrorism'],['examples','Czechoslovakia, Yugoslavia, Scotland']],['Idea']),2);
 sort('devolution',DEVO,'Which factor fits best: physical geography, ethnic separatism, irredentism, economic differences or terrorism?',{'physical geography':'Distance and terrain separate the regions: physical geography.','ethnic separatism':'A minority seeks self-rule: ethnic separatism.',irredentism:'A state claims land across its border on ethnic grounds: irredentism.','economic differences':'Regions are unequal in wealth and resent sharing it: economic differences.',terrorism:'Violence is used to pressure the government: terrorism.'},'Devolution factor');
 /* sovereignty */
 ask('sovereignty',[['What is a supranational organization?','an organization of several states that agree to share some authority to pursue common goals',['an organization within a single state','a company operating in several states'],'A supranational organization is a group of states that share some authority to pursue common goals, such as the EU or UN.'],
  ['What is the European Union (EU)?','a political and economic union of European member states with shared institutions and rules',['a military alliance of Asian states','a trade union of African workers'],'The European Union is a political and economic union of member states with shared institutions, laws and a single market.'],
  ['What is the United Nations (UN)?','a global organization of states founded in 1945 to promote peace, security and cooperation',['a regional trade bloc of Europe founded in 1957','an alliance of North Atlantic states founded in 1949'],'The United Nations was founded in 1945 to keep peace and promote cooperation among states. NATO was founded in 1949.'],
  ['Which supranational organization groups Southeast Asian states and was founded in 1967?','ASEAN',['the African Union','NATO'],'ASEAN, the Association of Southeast Asian Nations, was founded in 1967 to promote cooperation and trade among Southeast Asian states.'],
  ['Which organization promotes cooperation among African states and replaced the Organization of African Unity in 2002?','the African Union',['ASEAN','the European Union'],'The African Union replaced the Organization of African Unity in 2002 and promotes cooperation among African states.'],
  ['What is the euro?','a currency shared by many, but not all, EU member states',['the currency of every UN member','a European military'],'The euro is a shared currency used by many, but not all, EU members. Some members, like Denmark and Sweden, keep their own currency.'],
  ['Which idea was a prominent theme among supporters of the 2016 UK vote to leave the EU?','regaining more national sovereignty over laws and borders',['joining the euro','creating a larger common army'],'Many Leave supporters in the 2016 Brexit vote argued for taking back control of laws and borders, that is, more national sovereignty.'],
  ['How can membership in a supranational organization challenge sovereignty?','members may have to follow common rules or decisions even when their own governments disagree',['members lose all their territory','members must give up their governments'],'Members agree to follow shared rules and decisions, so a government may have to accept a rule it disagrees with.'],
  ['What is a trade bloc?','a group of states that lower trade barriers among themselves',['a group of states that forbid trade','an alliance that only shares military bases'],'A trade bloc is a group of states that lower tariffs and other trade barriers among themselves, such as USMCA or the EU.'],
  ['Which of these is mainly a military alliance?','NATO',['the EU','ASEAN'],'NATO is a military alliance pledging mutual defense. The EU and ASEAN are mainly political and economic organizations.'],
  ['How can the internet and global media challenge a state\'s sovereignty?','information, money and ideas cross borders in ways the state cannot easily control',['they make borders thicker','they remove all governments'],'Information, money and ideas flow across borders online, so a state cannot easily control what its people see or do.'],
  ['How can a transnational corporation challenge a state\'s control?','it can move jobs, investment and profits across borders in ways that limit a government\'s choices',['it is always controlled by a single state','it cannot operate in more than one country'],'A transnational corporation can move jobs, investment and profits between countries, which can pressure governments\' choices.'],
  ['How can separatist movements challenge sovereignty?','they dispute the state\'s authority over part of its territory',['they strengthen the state\'s authority','they only affect trade'],'Separatists dispute the state\'s authority over part of its territory, which challenges its sovereignty there.'],
  ['How can terrorism and insurgency challenge a state\'s sovereignty?','they threaten the state\'s ability to protect and control its territory',['they increase a state\'s control of its borders','they have no effect on a state'],'Terrorism and insurgency weaken a state\'s ability to protect its people and control its territory.']],tab('Challenges to sovereignty',[['UN','global, 1945'],['EU','Europe'],['ASEAN','Southeast Asia, 1967'],['AU','Africa, 2002']],['Idea']),1);
 sort('sovereignty',ORG,'Which organization fits: the UN, the EU, ASEAN or the African Union?',{'the UN':'It is the global organization with a General Assembly and Security Council: the UN.','the EU':'It is the European union with an elected parliament and common market: the EU.',ASEAN:'It is the Southeast Asian organization with its secretariat in Jakarta: ASEAN.','the African Union':'It is the African continental organization headquartered in Addis Ababa: the African Union.'},'Organization');
 /* forces */
 ask('forces',[['What is a centripetal force?','a force that unites people and holds a state together',['a force that divides a state and pulls it apart','a force that changes the climate'],'A centripetal force unites people and holds a state together, such as shared identity or a fair government.'],
  ['What is a centrifugal force?','a force that divides people and pulls a state apart',['a force that unites and strengthens a state','a force that raises tides'],'A centrifugal force divides people and pulls a state apart, such as ethnic conflict or regional inequality.'],
  ['Which is a centripetal force?','a shared national identity reinforced by symbols, holidays and schools',['deep ethnic and religious divisions','sharp inequality between regions'],'Shared symbols, holidays and schooling build a common national identity that unites people, so it is centripetal.'],
  ['Which is a centrifugal force?','a region that feels ignored and poorer than the rest',['a nationwide rail network that links regions','a national sports team that people cheer for together'],'A region that feels poor and ignored may resent the state and push for more self-rule, which pulls the state apart.'],
  ['How can a transport network be a centripetal force?','it links regions to each other and the capital, encouraging trade and contact',['it isolates regions from the capital','it creates new language differences'],'Roads and railways link regions to each other and the capital, helping trade and contact, which pulls people together.'],
  ['What is balkanization?','the fragmentation of a region into smaller, often hostile political units',['the merging of small states into a large one','the end of all borders'],'Balkanization is a region breaking into smaller, often hostile states, named after the Balkans, which split up repeatedly.'],
  ['What is a shatter belt?','a region caught between stronger powers that is often unstable and divided',['a coastline eroded by waves','a belt of fertile farmland'],'A shatter belt is a region caught between stronger powers, often divided and unstable, such as Eastern Europe in the 20th century.'],
  ['What is ethnic cleansing?','the systematic forced removal of an ethnic or religious group from an area, widely condemned and treated as a crime under international law',['a voluntary move of a group chosen by its members','a law that protects minority languages'],'Ethnic cleansing is forcing a group out of an area by violence or terror. It is not a separate crime in itself, but its acts are prosecuted as war crimes or crimes against humanity.'],
  ['Which breakup of the 1990s is often cited as centrifugal forces overcoming a multinational state?','Yugoslavia',['Iceland','Japan'],'Yugoslavia, home to several nations, broke apart in the 1990s amid war as divisions overcame the forces holding it together.'],
  ['How can a strong, fair government act as a centripetal force?','it can earn loyalty by providing services and treating regions fairly',['it must suppress all regional differences','it must be located on the coast'],'A government that provides services and treats all regions fairly earns loyalty, which helps hold a state together.'],
  ['Why can a single national language be a centripetal force?','it makes communication, schooling and national media easier across regions',['it prevents any trade','it makes cultural groups disappear overnight'],'A shared language makes it easier to talk, learn and share media across regions, which helps unite people.'],
  ['How can federalism act against centrifugal forces?','by giving regions some self-rule, which can ease demands to separate',['by removing all regional power','by dividing the country into more states by force'],'Federalism gives regions some self-rule, which can ease the pressure to separate and help keep the state together.']],tab('Forces on a state',[['centripetal','unites'],['centrifugal','divides'],['consequences','integration or breakup']],['Idea']),2);
 sort('forces',FORCE,'Is this a centripetal or a centrifugal force?',{centripetal:'It unites people and holds the state together: centripetal.',centrifugal:'It divides people and pulls the state apart: centrifugal.'},'Force');
}};
